def are_collinear(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    return (y3 - y2) * (x2 - x1) == (y2 - y1) * (x3 - x2)

def count_components(graph):
    visited = set()
    components = 0
    for node in graph:
        if node not in visited:
            components += 1
            stack = [node]
            while stack:
                curr = stack.pop()
                if curr not in visited:
                    visited.add(curr)
                    for neighbor in graph.get(curr, []):
                        stack.append(neighbor)
    return components

def simulate_ring_buffer(k, operations):
    buffer = [None] * k
    head = 0
    tail = 0
    size = 0
    results = []
    for op in operations:
        if op[0] == 'enqueue':
            val = op[1]
            buffer[tail] = val
            tail = (tail + 1) % k
            if size < k:
                size += 1
            else:
                head = (head + 1) % k
        elif op[0] == 'dequeue':
            if size == 0:
                results.append(-1)
            else:
                results.append(buffer[head])
                head = (head + 1) % k
                size -= 1
    return results

def is_bipartite(graph):
    color = {}
    for node in graph:
        if node not in color:
            queue = [node]
            color[node] = 0
            for curr in queue:
                for neighbor in graph.get(curr, []):
                    if neighbor not in color:
                        color[neighbor] = 1 - color[curr]
                        queue.append(neighbor)
                    elif color[neighbor] == color[curr]:
                        return False
    return True

def reverse_bits(n):
    res = 0
    for i in range(32):
        res = (res << 1) | (n & 1)
        n >>= 1
    return res

def sieve_primes(n):
    if n < 2: return []
    sieve = [True] * (n + 1)
    for x in range(2, int(n**0.5) + 1):
        if sieve[x]:
            for i in range(x*x, n + 1, x):
                sieve[i] = False
    return [i for i in range(2, n + 1) if sieve[i]]

def euler_totient(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def parse_cron_minutes(expr):
    if expr == '*':
        return list(range(60))
    if expr.startswith('*/'):
        step = int(expr[2:])
        return list(range(0, 60, step))
    if '-' in expr:
        start, end = map(int, expr.split('-'))
        return list(range(start, end + 1))
    if ',' in expr:
        return sorted(list(set(map(int, expr.split(',')))))
    return [int(expr)]

def stack_machine(instructions):
    stack = []
    for instr in instructions:
        parts = instr.split()
        if parts[0] == 'PUSH':
            stack.append(int(parts[1]))
        elif parts[0] == 'ADD':
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif parts[0] == 'SUB':
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif parts[0] == 'MUL':
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
    return stack[-1] if stack else None

def simulate_editor(commands):
    left, right = [], []
    for c in commands:
        if c == '<':
            if left:
                left.pop()
        elif c == '{':
            if left:
                right.append(left.pop())
        elif c == '}':
            if right:
                left.append(right.pop())
        else:
            left.append(c)
    return ''.join(left) + ''.join(reversed(right))

def parse_url_simple(url):
    res = {'scheme': '', 'host': '', 'port': None, 'path': '/'}
    if '://' in url:
        scheme, rest = url.split('://', 1)
        res['scheme'] = scheme
    else:
        rest = url

    path_idx = rest.find('/')
    if path_idx != -1:
        res['path'] = rest[path_idx:]
        host_port = rest[:path_idx]
    else:
        host_port = rest

    if ':' in host_port:
        host, port = host_port.split(':', 1)
        res['host'] = host
        res['port'] = int(port)
    else:
        res['host'] = host_port

    return res

