def rle_decode(s):
    res = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        count_str = ''
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1
        res.append(char * int(count_str))
    return ''.join(res)

def nth_catalan(n):
    if n <= 1: return 1
    dp = [0] * (n + 1)
    dp[0] = dp[1] = 1
    for i in range(2, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - j - 1]
    return dp[n]

def swap_without_temp(arr, i, j):
