def dijkstra(graph, start, target):
    import heapq
    pq = [(0, start)]
    visited = set()
    while pq:
        dist, node = heapq.heappop(pq)
        if node == target: return dist
        if node in visited: continue
        visited.add(node)
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                heapq.heappush(pq, (dist + weight, neighbor))
    return -1

def partitions(n):
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[j] += dp[j - i]
    return dp[n]

def simulate_rw_lock(ops):
    readers = 0
    writer = False
    res = []
    for op in ops:
        if op[0] == 'read_acquire':
            if not writer:
                readers += 1
                res.append(True)
            else:
                res.append(False)
        elif op[0] == 'read_release':
            if readers > 0:
                readers -= 1
            res.append(True)
        elif op[0] == 'write_acquire':
            if readers == 0 and not writer:
                writer = True
                res.append(True)
            else:
                res.append(False)
        elif op[0] == 'write_release':
            if writer:
                writer = False
            res.append(True)
    return res

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1: return points
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def matrix_multiply(A, B):
    if not A or not B or not A[0] or not B[0]: return None
    if len(A[0]) != len(B): return None
    result = [[0 for _ in range(len(B[0]))] for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(B[0])):
            for k in range(len(B)):
                result[i][j] += A[i][k] * B[k][j]
    return result

def subset_sum(nums, target):
    dp = [False] * (target + 1)
    dp[0] = True
    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True
    return dp[target]

def simulate_allocator(total_size, ops):
    blocks = [] # (start, size, id)
    results = []
    for op in ops:
        if op[0] == 'alloc':
            aid, size = op[1], op[2]
            start_idx = 0
            allocated = False
            for b in sorted(blocks, key=lambda x: x[0]):
                if b[0] - start_idx >= size:
                    blocks.append((start_idx, size, aid))
                    results.append(start_idx)
                    allocated = True
                    break
                start_idx = b[0] + b[1]
            if not allocated:
                if total_size - start_idx >= size:
                    blocks.append((start_idx, size, aid))
                    results.append(start_idx)
                else:
                    results.append(-1)
        elif op[0] == 'free':
            blocks = [b for b in blocks if b[2] != op[1]]
    return results
